/* eslint-disable react-native/no-inline-styles */
import React, {useState} from 'react';
import {View, TouchableOpacity} from 'react-native';
import WebView from 'react-native-webview';
import {AnyObj, buildLink, useAuthStore} from '@smarttestpro/smart-common';
import MaterialIcons from 'react-native-vector-icons/MaterialIcons';
import {NativeStackScreenProps} from '@react-navigation/native-stack';
import {ListAppsStackParamList} from '../../navigation/ListAppNavigator';

import {ActivityIndicator, Button, Text} from 'react-native-paper';

type Props = NativeStackScreenProps<
  ListAppsStackParamList,
  'StudentDashBoardScreen'
>;

const StudentDashBoardScreen = ({navigation, route}: Props) => {
  const {accessToken, refreshToken} = useAuthStore();
  const [error, setError] = useState(false);

  const [loading, setLoading] = useState(false);

  const [renderKey, setRenderKey] = useState(Date.now());
  const [showURI, setShowURI] = useState(false);

  const baseUrl = 'https://smarttest.pro';
  const url = `/${buildLink(
    `webview/parentstudent/${route.params.maHocSinh}`,
    {},
  )}`;
  const uri = route.params.maHocSinh
    ? `${baseUrl}/thanh-vien/dang-nhap?return_to=${encodeURI(
        url,
      )}&accessToken=${encodeURI(accessToken || '')}&refreshToken=${encodeURI(
        refreshToken || '',
      )}`
    : null;

  if (!uri) {
    return (
      <View>
        <Text>Vui lòng xem lại, bài giảng không tồn tại!</Text>
      </View>
    );
  }

  if (error) {
    return (
      <View
        style={{
          flex: 1,
          padding: 24,
          gap: 20,
          justifyContent: 'center',
          alignItems: 'center',
        }}>
        <Text variant="bodyLarge" style={{textAlign: 'center'}}>
          Có lỗi xảy ra, vui lòng kiểm tra mạng và bấm nút "Tải lại trang"!
        </Text>
        {showURI === true && <Text style={{textAlign: 'center'}}>{uri}</Text>}
        <Button
          mode="contained"
          onLongPress={() => {
            setShowURI(!showURI);
          }}
          onPress={() => {
            setRenderKey(Date.now());
            setLoading(true);
            setError(false);
          }}>
          Tải lại trang
        </Button>
      </View>
    );
  }

  return (
    <View className="flex-1 bg-gray-50">
      {/* Header */}
      <View className="bg-white shadow-sm">
        {/* Top Navigation Bar */}
        <View className="h-14 flex-row items-center px-4">
          <TouchableOpacity
            onPress={() => navigation.goBack()}
            className="mr-4">
            <MaterialIcons name="arrow-back" size={24} color="#1f2937" />
          </TouchableOpacity>
          <Text className="text-lg font-semibold text-gray-800 flex-1">
            {'Chi tiết'}
          </Text>
        </View>
      </View>

      <View style={{flex: 1, backgroundColor: '#fff'}}>
        {loading === true && (
          <View style={{padding: 20}}>
            <ActivityIndicator animating={true} />
          </View>
        )}
        <View className="flex-1 pb-2">
          <WebView
            originWhitelist={['*']}
            javaScriptEnabled
            domStorageEnabled
            onError={() => {
              setError(true);
              return (
                <View>
                  <Text>
                    Có lỗi xảy ra, vui lòng kiểm tra mạng và bấm nút "Tải lại
                    trang"!
                  </Text>
                </View>
              );
            }}
            onLoad={() => setLoading(false)}
            key={renderKey}
            cacheEnabled={true}
            onReceivedError={() => {
              return (
                <View>
                  <Text>
                    Có lỗi xảy ra, vui lòng kiểm tra mạng và bấm nút "Tải lại
                    trang"!
                  </Text>
                </View>
              );
            }}
            startInLoadingState={true}
            // renderLoading={() => <ActivityIndicator animating={true} />}
            renderError={() => {
              return (
                <View>
                  <Text>
                    Có lỗi xảy ra, vui lòng kiểm tra mạng và bấm nút "Tải lại
                    trang"!
                  </Text>
                </View>
              );
            }}
            source={{
              uri,
            }}
            style={{flex: 1}}
          />
        </View>
      </View>
    </View>
  );
};

export default StudentDashBoardScreen;
