import React, {useCallback, useEffect, useState} from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  ScrollView,
  RefreshControl,
} from 'react-native';
import MaterialIcons from 'react-native-vector-icons/MaterialIcons';
import {getListChildrent} from '../../api/dashboard-api';
import {useAuthStore} from '@smarttestpro/smart-common';
import {useNavStore} from '@smarttestpro/smart-common';

interface Student {
  maHocSinh: string;
  tenHocSinh: string;
  maPhuHuynh: string;
}

interface StudentCardProps {
  student: Student;
  onPress?: (student: Student) => void;
}

// Component definitions
const StudentCard: React.FC<StudentCardProps> = ({student, onPress}) => (
  <View className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 mb-4">
    <View className="flex-row items-center mb-3">
      <View className="w-12 h-12 bg-indigo-100 rounded-full items-center justify-center mr-3">
        <MaterialIcons name="school" size={24} color="#4f46e5" />
      </View>
      <View className="flex-1">
        <Text className="text-lg font-bold text-gray-900">
          {student.tenHocSinh}
        </Text>
        <Text className="text-sm text-gray-500">
          Mã học sinh: {student.maHocSinh}
        </Text>
      </View>
    </View>

    <TouchableOpacity
      className="bg-indigo-50 rounded-lg mt-3 p-3"
      onPress={() => onPress?.(student)}>
      <Text className="text-center text-indigo-600 font-semibold">
        Xem chi tiết
      </Text>
    </TouchableOpacity>
  </View>
);

const ParentScreen: React.FC = ({navigation}: any) => {
  const [data, setData] = useState<Student[]>([]);
  const [loading, setLoading] = useState(false);
  const {user} = useAuthStore();
  const [refreshing, setRefreshing] = useState(false);
  const {setNav} = useNavStore();

  const handleStudentPress = (student: Student): void => {
    navigation.push('StudentDashBoardScreen', {
      maHocSinh: student.maHocSinh,
    });
  };

  // const data: Student[] = [
  //   {
  //     maHocSinh: 'student01',
  //     tenHocSinh: 'Nguyen Van A',
  //     maPhuHuynh: 'hung',
  //   },
  // ];

  // Function to fetch data
  const fetchData = useCallback(
    async (isRefreshing = false) => {
      if (loading) {
        return;
      }

      setLoading(true);
      try {
        const response = await getListChildrent(user.preferred_username);
        setData(response.data);
      } catch (error) {
        console.error('Error fetching data:', error);
      } finally {
        setLoading(false);
        if (isRefreshing) {
          setRefreshing(false);
        }
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [loading],
  );

  useEffect(() => {
    setNav('dashboard', false);
    fetchData();

    return () => {
      setNav('dashboard', true);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <View className="flex-1 bg-gray-50">
      {/* Header */}
      <View className="bg-white shadow-sm">
        <View className="flex-row items-center px-4 h-14">
          <TouchableOpacity
            onPress={() => navigation.goBack()}
            className="w-10 h-10 items-center justify-center rounded-full hover:bg-gray-100">
            <MaterialIcons name="arrow-back" size={24} color="#374151" />
          </TouchableOpacity>

          <View className="flex-1 items-center mr-10">
            <Text className="text-xl font-bold text-gray-800">Phụ huynh</Text>
          </View>
        </View>
      </View>

      {/* Content */}
      <ScrollView className="flex-1 px-4 pt-4">
        <View className="bg-indigo-500 rounded-xl p-4 mb-6">
          <Text className="text-white text-lg font-semibold mb-1">
            Xin chào Phụ huynh!
          </Text>
          <Text className="text-indigo-100">
            Theo dõi thông tin học tập của con bạn tại đây
          </Text>
        </View>

        {data.map(student => (
          <StudentCard
            key={student.maHocSinh}
            student={student}
            onPress={handleStudentPress}
          />
        ))}

        <View className="h-4" />
      </ScrollView>
    </View>
  );
};

export default ParentScreen;
